;icon&#34;: &#34;fa-chart-line&#34;, &#34;isFavicon&#34;: true}, {&#34;title&#34;: &#34;Health Insurance&#34;, &#34;description&#34;: &#34;A choice of medical, dental and vision plans are offered to team members&#34;, &#34;image&#34;: null, &#34;imageAlt&#34;: null, &#34;icon&#34;: &#34;fa-plus-square&#34;, &#34;isFavicon&#34;: true}, {&#34;title&#34;: &#34;Recognition&#34;, &#34;description&#34;: &#34;We promote and reward peer-to-peer recognition&#34;, &#34;image&#34;: null, &#34;imageAlt&#34;: null, &#34;icon&#34;: &#34;fa-user-friends&#34;, &#34;isFavicon&#34;: true}]}, &#34;blogs&#34;: {&#34;items&#34;: [{&#34;title&#34;: &#34;Busy is the new stupid’ … or is it? Parkinson’s law revisited&#34;, &#34;description&#34;: &#34;Busy is the new stupid’ … or is it? Parkinson’s law revisited&#34;, &#34;image&#34;: &#34;https://dmassets.micron.com/is/image/microntechnology/605874721-ai-neon-lines-tertiary&#34;, &#34;url&#34;: &#34;https://www.micron.com/about/blog/company/insights/busy-is-the-new-stupid-or-is-it-parkinsons-law-revisited&#34;}, {&#34;title&#34;: &#34;Micron s commitment to meeting customer demand and operational excellence&#34;, &#34;description&#34;: &#34;Micron s commitment to meeting customer demand and operational excellence&#34;, &#34;image&#34;: &#34;https://dmassets.micron.com/is/image/microntechnology/adobestock-195025829-tertiary&#34;, &#34;url&#34;: &#34;https://www.micron.com/about/blog/company/insights/microns-commitment-to-meeting-customer-demand-and-operational-excellence&#34;}, {&#34;title&#34;: &#34;Welcome to New York: Micron selects an office location as megafab progresses&#34;, &#34;description&#34;: &#34;Welcome to New York: Micron selects an office location as megafab progresses&#34;, &#34;image&#34;: &#34;https://dmassets.micron.com/is/image/microntechnology/blog-cny-office-tertiary&#34;, &#34;url&#34;: &#34;https://www.micron.com/about/blog/company/community/welcome-to-new-york-micron-selects-an-office-location-as-megafab-progresses&#34;}]}, &#34;videos&#34;: {&#34;items&#34;: [&#34;https://www.youtube.com/embed/pFf7siXrLPE&#34;, &#34;https://www.youtube.com/embed/gh_C7T7TfDg&#34;, &#34;https://www.youtube.com/embed/JfeId9yU-uc&#34;]}, &#34;positionFields&#34;: {&#34;fields&#34;: [{&#34;fieldName&#34;: &#34;display_job_id&#34;, &#34;label&#34;: &#34;Job ID&#34;, &#34;type&#34;: &#34;text&#34;, &#34;format&#34;: null}], &#34;fieldsToDisplay&#34;: null}, &#34;positionInsightsConfig&#34;: {&#34;enabled&#34;: true, &#34;insightsFields&#34;: [&#34;skills&#34;, &#34;company&#34;, &#34;experience_years&#34;, &#34;titles&#34;], &#34;insightsFq&#34;: null, &#34;sourceInsightsFromGroupId&#34;: null}, &#34;pymwwConfig&#34;: {&#34;isEnabled&#34;: false, &#34;fq&#34;: &#34;&#34;}, &#34;positionCustomContent&#34;: {&#34;items&#34;: [{&#34;body&#34;: &#34;&lt;div class= headers &gt;&lt;a href= https://www.micron.com/about/sustainability/micron-gives class= a-link target= _blank &gt;Micron Foundation &lt;/a&gt;&lt;/div&gt;&lt;br&gt; Strong communities and education are vital to the success of both society and innovative companies. Every Micron site understands the complex needs of their local community. Whether it’s through strategic giving, sponsorships or deploying team member volunteers, we are making a difference.&lt;br&gt;&lt;br&gt; &lt;div class= headers &gt;&lt;a href= https://www.micron.com/about/our-commitment/operating-thoughtfully/sustainability class= a-link target= _blank &gt;Sustainability&lt;/a&gt;&lt;/div&gt;&lt;br&gt;Micron is committed to sustainable practices and supporting our global community. We are building and maintaining sustainable operations, products, and communities while focusing on opportunities and risks that are most important to our business success and stakeholders.&lt;br&gt;&lt;br&gt;&#34;, &#34;title&#34;: &#34;&#34;}, {&#34;body&#34;: &#34;&#34;, &#34;title&#34;: &#34;&#34;}, {&#34;body&#34;: &#34;&#34;, &#34;title&#34;: &#34;&#34;}]}, &#34;matchDetailsConfig&#34;: {&#34;enabled&#34;: true, &#34;showTopApplicantInsights&#34;: false, &#34;allowMocInsights&#34;: false, &#34;showRelevantExperience&#34;: true, &#34;showPreviouslyWorkedAt&#34;: true, &#34;showWorkCategoryOverlap&#34;: true, &#34;showSchool&#34;: true, &#34;showSkills&#34;: true}, &#34;similarPositionConfig&#34;: {&#34;showSimilarJobsOrderedByViewedPositionLocation&#34;: false, &#34;similarJobLookupRadiusKm&#34;: 20}}, &#34;efJdOverridesAtsPosting&#34;: false}, &#34;branding&#34;: {&#34;companyName&#34;: &#34;Micron Technology&#34;, &#34;companyLogo&#34;: &#34;https://static.vscdn.net/images/careers/demo/micron/1750097203::ta-2278650-web-hero-image-careers-page-v02a.jpg&#34;, &#34;privacyHtml&#34;: &#34;&lt;p&gt;Micron uses an artificial intelligence (\&#34;AI\&#34;) recruiting software provided by Eightfold AI to assist with and support its recruiting efforts. Before submitting your application to &lt;a href=’https://micron.eightfold.ai/careers’ target=’_blank’&gt;https://micron.eightfold.ai/careers&lt;/a&gt; (the \&#34;Platform\&#34;), please review Micron rsquo;s &lt;a href=’https://www.micron.com/Privacy/applicant-Privacy-Notice’ target=’_blank’&gt;&lt;u&gt;Applicant Privacy Notice&lt;/u&gt;&lt;/a&gt; to understand how your personal data is processed, as well as this Notice Related to Micron rsquo;s Use of the Eightfold AI Recruiting Software (\&#34;Notice\&#34;). You may also review Eightfold AI rsquo;s responsible AI Principles here: &lt;a href=’https://trust.eightfold.ai/’ target=’_blank’&gt;https://trust.eightfold.ai/&lt;/a&gt;.&lt;/p&gt;&lt;p&gt;Micron rsquo;s use of the Eightfold AI recruiting software in connection with your application may be subject to various AI-related laws and regulations:&lt;/p&gt;&lt;ol style=’margin-left: 40px; padding-left: 0;’&gt;&lt;li style=’margin-bottom: 8px;’&gt;&lt;b&gt;U.S. State and Local Laws:&lt;/b&gt; Depending on where you reside, the Platform may constitute a high-risk AI system that makes, or is a substantial factor in making, a consequential decision and/or an \&#34;automated employment decision tool,\&#34; as those terms are defined by applicable U.S. law.&lt;/li&gt;&lt;li style=’margin-bottom: 8px;’&gt;&lt;b&gt;EU Artificial Intelligence Act (\&#34;EU AI Act\&#34;):&lt;/b&gt; The EU AI Act classifies AI systems used in recruitment and employment decisions as \&#34;high-risk\&#34; under Annex III. The EU AI Act applies not only to deployers established in the EU, but also where AI outputs (such as matching scores or candidate rankings) are used by personnel located in the EU, or where the recruitment process relates to a position located in the EU (see below).&lt;/li&gt;&lt;/ol&gt;&lt;p&gt;For applications submitted through the Platform, Micron recruiters will use the assistance of the Eightfold AI recruiting software to identify your skills based on the information in your resume and other application materials, and to help assess how closely your skills match the defined requirements for open roles.&lt;/p&gt;&lt;p&gt;While submitting your application through the Platform is not required, we encourage you to do so (as explained below).&lt;/p&gt;&lt;p&gt;If you click \&#34;Submit\&#34; below:&lt;/p&gt;&lt;ol style=’margin-left: 20px; padding-left: 0;’&gt;&lt;li style=’margin-bottom: 8px;’&gt;Micron will provide job recommendations to you, which will be displayed on the Platform.&lt;/li&gt;&lt;li style=’margin-bottom: 8px;’&gt;The Platform will use AI to inform the human recruiter of skills you may have that are not listed on your resume, based on your career history and work experience listed in your resume or other application materials.&lt;/li&gt;&lt;li style=’margin-bottom: 8px;’&gt;The Platform will also display to the Micron recruiter information obtained from publicly accessible professional-oriented websites, such as your public LinkedIn profile, that you have listed in your resume or application materials.&lt;/li&gt;&lt;li style=’margin-bottom: 8px;’&gt;The Platform will assign a match score based on how closely your stated and inferred skills match the requirements for the open role based on the content of your application, the Platform rsquo;s analysis described above and Micron rsquo;s configuration of the skill and AI qualification matching software. While this match score may influence which applications receive prioritized attention from recruiters, it does not automatically determine hiring outcomes. Such decisions are always made by Micron recruiters.&lt;/li&gt;&lt;li style=’margin-bottom: 8px;’&gt;These unique features of the Platform help us ensure that we don rsquo;t miss what you have to offer based on the skills we are looking for. They also support our efforts to eliminate bias in the recruitment process.&lt;/li&gt;&lt;li style=’margin-bottom: 8px;’&gt;If your application is unsuccessful, we will keep your information so our recruiters can match you with future roles, and contact you if they think you may be a fit for open positions.&lt;/li&gt;&lt;li style=’margin-bottom: 8px;’&gt;Regardless of any AI assistance in the recruitment process, Micron recruiters use their professional judgment to make all decisions regarding whether to advance candidates in the hiring process. Micron recruiters do not solely relying on match scores.&lt;/li&gt;&lt;/ol&gt;&lt;p&gt;If you have any questions about this Notice, including Micron rsquo;s deployment of AI systems as part of its recruiting efforts or to request a reasonable accommodation, please contact us as follows:&lt;/p&gt;&lt;p style=’margin-left: 40px; margin-bottom: 6px;’&gt;&lt;b&gt;A. Via Email.&lt;/b&gt; You may contact us by email at &lt;a href=’mailto:privacy@micron.com’&gt;privacy@micron.com&lt;/a&gt;.&lt;/p&gt;&lt;p style=’margin-left: 40px; margin-bottom: 6px;’&gt;&lt;b&gt;B. Via Telephone.&lt;/b&gt; You may also contact us by telephone at +1-800-336-8915.&lt;/p&gt;&lt;p style=’margin-left: 40px; margin-bottom: 6px;’&gt;&lt;b&gt;C. Via Direct Mail.&lt;/b&gt; You may contact us by direct mail at:&lt;/p&gt;&lt;p style=’margin-left: 80px; margin-bottom: 16px;’&gt;Micron Technology, Inc.&lt;br&gt;Attn: Legal-Privacy&lt;br&gt;8000 South Federal Way&lt;br&gt;Post Office Box 6&lt;br&gt;Boise, Idaho 83707-0006, USA&lt;/p&gt;&lt;p&gt;&lt;b&gt;Additional Information for Applicants Applying to Roles in the EU and/or Those Applying from the EU&lt;/b&gt;&lt;/p&gt;&lt;p&gt;This specific section applies to applications for roles located in the EU and/or to candidates applying from the EU. It explains how Micron uses an AI system in recruitment and the safeguards we apply in accordance with the EU AI Act.&lt;/p&gt;&lt;ul style=’margin-left: 20px; padding-left: 0; list-style-type: disc;’&gt;&lt;li style=’margin-bottom: 10px;’&gt;&lt;b&gt;Type of AI Technology:&lt;/b&gt; Micron uses the Eightfold AI recruiting software, a machine-learning talent-intelligence platform that uses natural-language processing to parse resumes, infer candidate skills and calculate compatibility scores with open positions. Since it is used to support recruitment and selection decisions, this tool is treated as a \&#34;high-risk\&#34; AI system under the EU AI Act rsquo;s Annex covering employment-related AI uses.&lt;/li&gt;&lt;li style=’margin-bottom: 10px;’&gt;&lt;b&gt;The Purpose for Which It Is Used:&lt;/b&gt; The Eightfold AI recruiting software is used to: (a) identify skills from your resume and career history; (b) match your qualifications against role requirements; (c) highlight applications that may be strong fits for recruiter review; and (d) recommend other open positions you may wish to consider.&lt;/li&gt;&lt;li style=’margin-bottom: 10px;’&gt;&lt;b&gt;Impact on Employment Decisions:&lt;/b&gt; The Eightfold AI recruiting software generates matching scores and skill inferences. AI outputs are decision-support only. Micron recruiters mdash;trained to exercise independent judgment and avoid automation bias mdash;review applications and make all decisions to interview, hire or reject. We do not automatically reject any candidate based solely on AI analysis, and every application routed through the Platform is reviewed by a human recruiter.&lt;/li&gt;&lt;li style=’margin-bottom: 10px;’&gt;&lt;b&gt;Information and rights:&lt;/b&gt;&lt;ul style=’margin-left: 20px; margin-top: 8px; padding-left: 0; list-style-type: circle;’&gt;&lt;li style=’margin-bottom: 8px;’&gt;If you prefer not to have your application processed using the AI-assisted tools described above, you may submit your resume directly to &lt;a href=’mailto:TA_EMEA@micron.com’&gt;&lt;u&gt;TA_EMEA@micron.com&lt;/u&gt;&lt;/a&gt; along with the Req Id number listed in the job description. Your resume will be forwarded to the appropriate recruiter for review without the use of the Eightfold AI recruiting software.&lt;/li&gt;&lt;li style=’margin-bottom: 8px;’&gt;You may lodge a complaint with the competent national market surveillance authority under the EU AI Act, and you retain all rights under EU data protection law (see Micron rsquo;s &lt;a href=’https://www.micron.com/Privacy/applicant-Privacy-Notice’ target=’_blank’&gt;&lt;u&gt;Applicant Privacy Notice&lt;/u&gt;&lt;/a&gt;).&lt;/li&gt;&lt;li style=’margin-bottom: 8px;’&gt;You may also contact us directly with questions about this Notice or about how the Eightfold AI recruiting software was used in connection with your application by using the contact information provided above.&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;/ul&gt;&#34;, &#34;privacy&#34;: {&#34;defaultLoggedOutContactConsent&#34;: null, &#34;defaultLoggedOutCampaignConsent&#34;: null}, &#34;customPageSections&#34;: {&#34;footer&#34;: &#34;&#34;, &#34;customNavbarConfig&#34;: {&#34;enable&#34;: true, &#34;html&#34;: &#34;&lt;nav id= navbar-section class= navbar1 navbar navbar-expand-lg navbar-light bg-light style= z-index: 999999 !important; &gt; &lt;div class= navholder &gt; &lt;div class= logoholder &gt;&lt;a class= href= https://www.micron.com/careers style=