comm leisten, hat Auswirkungen auf das Leben rund um den Globus – und Sie können ein Teil davon sein. Bewerben Sie sich noch heute und entfalten Sie Ihr volles Potenzial..&lt;/p&gt;\&#34;;}}, 2500);setTimeout(function(){if (navigator.userAgent.match(/Android/i) || navigator.userAgent.match(/webOS/i) || navigator.userAgent.match(/iPhone/i) || navigator.userAgent.match(/iPad/i) || navigator.userAgent.match(/iPod/i) || navigator.userAgent.match(/BlackBerry/i) || navigator.userAgent.match(/Windows Phone/i)) {document.getElementsByClassName( col-md-4 match-and-insights-column )[0].innerHTML = \&#34;&lt;p&gt;&lt;b&gt;&lt;h2&gt;Job Application Privacy Notice&lt;/h2&gt;&lt;/b&gt;&lt;/p&gt;&lt;p&gt;&lt;a style= color: var(--anchor-color); href= https://www.qualcomm.com/site/job-application-privacy-notice target= _blank &gt;Job Application Privacy Notice&lt;/a&gt;&lt;/p&gt;&lt;p&gt;&lt;b&gt;&lt;h2&gt;Use of AI in the Application Process&lt;/h2&gt;&lt;/b&gt;&lt;/p&gt;&lt;p&gt;&lt;a style= color: var(--anchor-color); href= https://qualcomm.com/site/privacy/ai-in-the-application-process target= _blank &gt;Use of AI in the Application Process&lt;/a&gt;&lt;/p&gt;&lt;p&gt;&lt;b&gt;&lt;h2&gt;Equal Employment Opportunity&lt;/h2&gt;&lt;/b&gt;&lt;/p&gt;&lt;p&gt;&lt;a style= color: var(--anchor-color); href= https://www.eeoc.gov/sites/default/files/2023-06/22-088_EEOC_KnowYourRights6.12ScreenRdr.pdf target= _blank &gt;Equal Employment Opportunity&lt;/a&gt;&lt;/p&gt;&lt;p&gt;&lt;a style= color: var(--anchor-color); href= https://secure-web.cisco.com/127mgKhgxmcaCmExx9Yc1A1fJyGZGIUqhMEt6v5fg05pq-tUXRIpFWMWukhyo8r6jxCd0dYsJzr64HregOmS5c4Bckwywixis7-80AhhlMuwGjdC7WR0yBdsh7sNvWfiz-xg5sj8I8w2jv-iGrviJibPVW3JH9YG8RWegouUykF7pYcXJzbdQ11X-YxcrRTPXjZr4pupkxTjvqGtIme1dinO7mzYMudqCqeolIj5b2xecEjofV5HjrBbSv7xD2C2T93BkUoMg1Ql41YAbibA5aLw3NfuM-hjR5w1qGmnNSjJrIoIVJCNBJ0F3z-JW0i1HEH19ovckQRRRWeq1OUR4BY5N1MBaHG-pEIFTpIs-IwCLXNvRySdD0VY_kpGt_S3wJY-VEjSSbbVWxI3PApUBdL3P7BmnT_yu5wkqJludGBfkD6mgP5VPkBpmgJ5Gb